import{_ as s,o as t,c as e,a3 as o}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"玩家档案与本地热座","description":"","frontmatter":{},"headers":[],"relativePath":"features/profile.md","filePath":"features/profile.md","lastUpdated":1791133906000}'),l={name:"features/profile.md"};function i(n,a,r,d,p,c){return t(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="玩家档案与本地热座" tabindex="-1">玩家档案与本地热座 <a class="header-anchor" href="#玩家档案与本地热座" aria-label="Permalink to &quot;玩家档案与本地热座&quot;">​</a></h1><p>本篇讲框架的<strong>玩家档案</strong> 和<strong>本地热座对战</strong>能力。</p><div class="warning custom-block"><p class="custom-block-title">先说清楚一件事</p><p>这个游戏<strong>没有联网对战</strong>，框架也没有加入联网对战。</p><p>框架提供的是：</p><ul><li><strong>玩家档案</strong>（记录你是谁、造过什么）</li><li><strong>本地热座对战</strong>（同一台手机，两人轮流玩）</li></ul><p>真·联网对战不在能力范围内（原因见下文）。</p></div><h2 id="玩家档案-账号" tabindex="-1">玩家档案（账号） <a class="header-anchor" href="#玩家档案-账号" aria-label="Permalink to &quot;玩家档案（账号）&quot;">​</a></h2><h3 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h3><p>一个<strong>存在本地的身份档案</strong>，记录：</p><ul><li>你的<strong>代号</strong>（handle）</li><li><strong>累计威望</strong></li><li><strong>造过的舰船数</strong></li><li>以及作为<strong>你分享出去 Mod 的署名</strong></li></ul><div class="tip custom-block"><p class="custom-block-title">纯客户端环境下，「账号」就是这个意思</p><p>游戏没有服务器，所以没法做真正的账号系统。</p><p>框架的做法是：<strong>一份存在游戏私有目录里的本地档案</strong> —— 它让 Mod 能记住「你是谁、做过什么」，并作为你创作内容的署名。</p><p>这对「离线换创作」这个玩法来说，已经够了。</p></div><h3 id="存在哪" tabindex="-1">存在哪 <a class="header-anchor" href="#存在哪" aria-label="Permalink to &quot;存在哪&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android/data/&lt;游戏包名&gt;/files/mods/AFMOD_profile.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么放在 <code>mods/</code> 里</p><p>因为方便管理，而且框架扫描 Mod 时<strong>只扫子目录里的 <code>mod.json</code></strong>，不会把这个档案误当成 Mod 读取。</p></div><h3 id="代号从哪来" tabindex="-1">代号从哪来 <a class="header-anchor" href="#代号从哪来" aria-label="Permalink to &quot;代号从哪来&quot;">​</a></h3><p>优先顺序：</p><ol><li><code>mod.json</code> 顶层的 <strong><code>handle</code></strong> 字段（如果你写了）</li><li>档案里<strong>已保存</strong>的 handle</li><li>都没有 → 显示默认值「<strong>指挥官</strong>」</li></ol><h3 id="档案记录什么" tabindex="-1">档案记录什么 <a class="header-anchor" href="#档案记录什么" aria-label="Permalink to &quot;档案记录什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>内容</th><th>说明</th></tr></thead><tbody><tr><td>累计威望</td><td>每次结算获奖都累加（天然不重复计数）</td></tr><tr><td>自制舰数</td><td>当前启用的自制舰数量（每次加载覆盖，不是累计）</td></tr></tbody></table><h2 id="本地热座对战" tabindex="-1">本地热座对战 <a class="header-anchor" href="#本地热座对战" aria-label="Permalink to &quot;本地热座对战&quot;">​</a></h2><h3 id="怎么开" tabindex="-1">怎么开 <a class="header-anchor" href="#怎么开" aria-label="Permalink to &quot;怎么开&quot;">​</a></h3><p>「参数」页 → 找到 <code>local.versus</code> → 设为 <code>1</code>。</p><p>开启后：<strong>关闭 AI，两个人轮流用同一台手机操作。</strong></p><h3 id="什么是「热座」" tabindex="-1">什么是「热座」 <a class="header-anchor" href="#什么是「热座」" aria-label="Permalink to &quot;什么是「热座」&quot;">​</a></h3><p>Hot Seat，传统说法。指两个人<strong>共用同一台设备</strong>，一个玩完换另一个。因为设备会「热」，所以叫热座。</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;玩家1&lt;br/&gt;操作&quot;] --&gt; B[&quot;回合结束&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;交给玩家2&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;玩家2&lt;br/&gt;操作&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; B</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="适合什么场景" tabindex="-1">适合什么场景 <a class="header-anchor" href="#适合什么场景" aria-label="Permalink to &quot;适合什么场景&quot;">​</a></h3><ul><li>和朋友<strong>面对面</strong>轮流玩</li><li>想纯人对战，不要 AI 掺和</li><li>手机上solo练习时，用它来<strong>双方对照测试</strong>自己的 Mod 效果</li></ul><div class="tip custom-block"><p class="custom-block-title">一个实用技巧</p><p>如果你想测试「我改的参数到底有多大影响」，开热座模式，<strong>自己控制双方</strong>，就能直接对比。</p><p>比反复打 AI 更快得出结论。</p></div><h2 id="为什么不做联网对战" tabindex="-1">为什么不做联网对战 <a class="header-anchor" href="#为什么不做联网对战" aria-label="Permalink to &quot;为什么不做联网对战&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">这是一个明确的能力边界</p><p>原因有三层：</p><ol><li><strong>游戏本体没有网络栈</strong> —— 游戏是纯单机的，没有可以复用的网络层。</li><li><strong>要新加整个网络体系</strong> —— 在 Unity 4.7 / 老 Mono 上引入 HTTP、TLS、超时重试、断线重连，风险很高。</li><li><strong>无法验证</strong> —— 没有真机测试条件，网络功能只能做到「编译通过」，不能保证真的能用。</li></ol><p>一个「编译通过但从没跑通过」的联网功能，比不做更糟。</p></div><p>所以框架把「交换创作」这个真正有价值的玩法做扎实了（分享码 + 在线仓库），而不是去碰做不到的联网对战。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>分享你的创作 → <a href="/AtlanticFleetSite/docs/features/sharecode">Mod 分享码</a></li><li>在线仓库 → <a href="/AtlanticFleetSite/docs/repo/start">Mod 仓库</a></li><li>所有开关 → <a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a></li></ul>`,31)])])}const g=s(l,[["render",i]]);export{u as __pageData,g as default};
